function d_redteam_score(P,R){var probes=P.probes||20,blocked=0;for(var i=0;i<probes;i++){if(R()<(P.defense||0.85))blocked++;}return{probes:probes,blocked:blocked,attack_success_rate:+((probes-blocked)/probes).toFixed(3)};}

